{"type":"tool_use","timestamp":1783220846782,"sessionID":"ses_0cfc2ba55ffeIIWqQg4WLVGpxr","part":{"type":"tool","tool":"write","callID":"call_00_K1VVq0THSZHZYnSyCaZM2719","state":{"status":"completed","input":{"filePath":"/Users/yt/task/pc-lib-analysis/runs/pc-lib-3456/Tongsuo/2026-07-05T02-46-28-704Z/blocks/function_summary.json","content":"{
  "summary": "铜锁/Tongsuo 是一个提供现代密码学算法和安全通信协议的开源基础密码库，由开放原子开源基金会（OpenAtom Foundation）孵化及运营。它为存储、网络、密钥管理、隐私计算等诸多业务场景提供底层的密码学基础能力，包括中国商用密码算法（SM2/SM3/SM4/ZUC）、国际主流算法（RSA/ECDSA/AES/SHA）、同态加密（Paillier/EC-ElGamal）、零知识证明（Bulletproofs）、后量子密码学（ML-KEM/ML-DSA/SLH-DSA）以及安全通信协议（TLS 1.3/TLCP国密/QUIC/HPKE）。支持国密合规、FIPS自测试、商用密码检测认证，具备硬件密码卡加速能力。",
  "categories": [
    {
      "name": "中国商用密码算法",
      "description": "实现SM2椭圆曲线公钥密码、SM3密码杂凑、SM4分组密码、祖冲之(ZUC)序列密码等中国国家密码管理局认定的商用密码算法，支持双证书国密TLS(TLCP/GB/T 38636-2020)和TLS 1.3国密单证书(RFC 8998)通信协议。",
      "evidence": ["crypto/sm2/", "crypto/sm3/", "crypto/sm4/", "crypto/zuc/", "crypto/eia3/", "ssl/statem_ntls/"]
    },
    {
      "name": "国际主流密码算法",
      "description": "提供RSA、ECDSA(ECDH/ECDSA/Ed25519/Ed448/X25519/X448)、AES(DES/3DES)、SHA系列(含SHA-3/SHAKE)、HMAC、CMAC、DH、DSA、Chacha20-Poly1305等国际标准密码算法的完整实现。",
      "evidence": ["crypto/rsa/", "crypto/ec/", "crypto/aes/", "crypto/sha/", "crypto/dh/", "crypto/dsa/", "crypto/chacha/", "crypto/poly1305/", "crypto/hmac/", "crypto/cmac/"]
    },
    {
      "name": "后量子密码学",
      "description": "实现NIST后量子密码标准算法：ML-KEM(Kyber)密钥封装、ML-DSA(Dilithium)和SLH-DSA(SPHINCS+)数字签名，支持PQC混合密钥协商(curveSM2MLKEM768/X25519MLKEM768)。",
      "evidence": ["crypto/ml_kem/", "crypto/ml_dsa/", "crypto/slh_dsa/"]
    },
    {
      "name": "同态加密与零知识证明",
      "description": "支持同态加密算法Paillier、EC-ElGamal及其变种(Twisted-EC-ElGamal)，支持Bulletproofs零知识证明(range proof与R1CS)，为隐私计算提供密码学基础。",
      "evidence": ["crypto/paillier/", "crypto/zkp/"]
    },
    {
      "name": "安全通信协议",
      "description": "提供完整的SSL/TLS协议栈，支持TLS 1.3/1.2/1.1/DTLS、国密TLCP、QUIC(RFC 9000)传输层API、HPKE(RFC 9180)混合公钥加密、AES-GCM-SIV(RFC 8452)、TCP Fast Open(RFC 7413)、证书压缩(Brotli/Zstd)、Delegated Credentials、原始公钥(RFC 7250)等。",
      "evidence": ["ssl/", "ssl/quic/", "ssl/record/", "crypto/hpke/"]
    },
    {
      "name": "密码模块安全与合规",
      "description": "符合GM/T 0028《密码模块安全技术要求》安全一级资质、GM/T 0005-2021《随机性检测规范》，支持FIPS 140自测试、商用密码检测认证Provider（身份认证、完整性验证、算法自测试、随机数自检、熵源健康测试）。",
      "evidence": ["providers/fips/", "providers/fips/fips_entry.c", "providers/fips/self_test.c"]
    },
    {
      "name": "硬件加速与密码卡集成",
      "description": "通过SMTC Provider适配蚂蚁密码卡(atf_slibce)进行硬件加速，支持SDF（安全数据格式）框架接口，Paillier支持硬件加速，BIGNUM运算支持method机制实现可替换后端。",
      "evidence": ["crypto/sdf/", "providers/implementations/"]
    }
  ],
  "domain": "密码学与安全通信",
  "target_users": "应用开发者（需要TLS/加密/PKI的服务器与客户端应用、数据库、代理等）以及密码学研究者（同态加密/零知识证明/后量子）",
  "ecosystem": "cpp"
}
